// 1. Captura a entrada do nó do Gemini
const item = $input.first().json;

// Função para extrair APENAS o texto da mensagem de forma limpa
function extrairTexto(obj) {
  if (typeof obj === 'string') return obj;
  if (!obj) return '';

  // Se a estrutura tiver parts (padrão Gemini)
  if (obj.content && Array.isArray(obj.content.parts)) {
    return obj.content.parts.map(p => p.text || '').join('');
  }

  if (typeof obj.content === 'string') return obj.content;
  if (typeof obj.text === 'string') return obj.text;
  if (typeof obj.output === 'string') return obj.output;
  if (obj.message && typeof obj.message.content === 'string') return obj.message.content;

  return typeof obj === 'object' ? JSON.stringify(obj) : String(obj);
}

let rawText = extrairTexto(item);

// 2. Limpa formatações Markdown (```json ... ```)
rawText = String(rawText)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Mantém o restante do seu fluxo para retornar a propriedade "mensagem"
return [
  {
    json: {
      nome: item.nome || "Cliente",
      email: item.email || "",
      mensagem: rawText
    }
  }
];

// 1. Obter o CSV do HTTP Request
const csvText = $("HTTP Request").first().json.data;

const linhas = csvText.trim().split('\n').map(l => l.trim()).filter(l => l.length > 0);
const cabecalhos = linhas[0].split(',').map(h => h.trim());

const investimentos = linhas.slice(1).map(linha => {
  const valores = linha.split(',').map(v => v.trim());
  const objeto = {};
  cabecalhos.forEach((cabecalho, index) => {
    objeto[cabecalho] = valores[index];
  });
  return objeto;
});

// 2. Capturar clientes do Webhook
const dadosWebhook = $("Webhook").first().json;
const clientes = dadosWebhook.body?.clientes || dadosWebhook.clientes || [];

// 3. Montar dados consolidados dos clientes com suas opções
const dadosConsolidados = clientes.map(cliente => {
  const opcoesRecomendadas = investimentos.filter(
    inv => inv.perfil.toLowerCase() === cliente.perfil.toLowerCase()
  );
  return {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: cliente.perfil,
    opcoes: opcoesRecomendadas
  };
});

// Retorna TUDO em um único item para fazer apenas 1 chamada na API do Gemini
// Substitua esta linha final:
// return [{ json: { clientes_processados: dadosConsolidados } }];

// Por esta:
return dadosConsolidados.map(cliente => ({ json: cliente }));
